//! Lane 5bB's red tests (the wave 5b base): every case of the TypeScript
//! dialect tests that calls a native or Hermes hook, replayed against `derm hook` from
//! `contracts/fixtures/hook-cases/5bB.json` by `support/replay.rs`. Generated by
//! `contracts/fixtures/hook-cases/gen.mjs`; do not edit by hand. They fail on
//! the base, whose dialects are stubs, and pass when the lane is done.
//! Run with `cargo test -p derm-cli --test hook_cases_5bB`.
//! Unix only: the recordings are Linux's and the replay's fake daemon is
//! a Unix socket (`support/replay.rs`); a Windows run waits for a Windows
//! fake daemon (the wave 5b close, "Come back to").
#![cfg(unix)]

mod support;

const CASES: &str = include_str!("../../../contracts/fixtures/hook-cases/5bB.json");

